import { useState, type FormEvent } from 'react'
import type { Work } from '../../interfaces/work'
import { ui } from '../../utils/ui'
import { decimalPattern, parseDecimal } from '../../utils/validation'

// The same limit as EstimateRules on the server, which stays the authoritative check.
const quantityPattern = decimalPattern(3)

interface AddWorkFormProps {
  works: Work[]
  onAdd: (workId: number, quantity: number) => Promise<void>
}

/** Picks a catalog work and a quantity to add to the estimate; its materials are generated by the server. */
export default function AddWorkForm({ works, onAdd }: AddWorkFormProps) {
  const [workId, setWorkId] = useState('')
  const [quantity, setQuantity] = useState('')
  const [error, setError] = useState<string | null>(null)
  const [adding, setAdding] = useState(false)

  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault()
    if (!workId) return setError('Pasirinkite darbą.')
    if (!quantityPattern.test(quantity.trim()) || parseDecimal(quantity) <= 0) {
      return setError('Kiekis turi būti didesnis už 0, ne daugiau kaip 3 skaitmenys po kablelio.')
    }

    setError(null)
    setAdding(true)
    try {
      await onAdd(Number(workId), parseDecimal(quantity))
      setWorkId('')
      setQuantity('')
    } finally {
      setAdding(false)
    }
  }

  return (
    <form className="my-4 flex flex-wrap items-end gap-3" onSubmit={handleSubmit} noValidate>
      <div className={ui.field}>
        <label className={ui.label} htmlFor="add-work">
          Darbas
        </label>
        <select id="add-work" className={ui.input} value={workId} onChange={(event) => setWorkId(event.target.value)}>
          <option value="">Pasirinkite…</option>
          {works.map((work) => (
            <option key={work.id} value={work.id}>
              {work.name} ({work.unit})
            </option>
          ))}
        </select>
      </div>
      <div className={ui.field}>
        <label className={ui.label} htmlFor="add-quantity">
          Kiekis
        </label>
        <input
          id="add-quantity"
          className={`${ui.input} w-32`}
          type="text"
          inputMode="decimal"
          autoComplete="off"
          value={quantity}
          onChange={(event) => setQuantity(event.target.value)}
        />
      </div>
      <button type="submit" className={ui.primaryButton} disabled={adding}>
        {adding ? 'Pridedama…' : 'Pridėti darbą'}
      </button>
      {error && (
        <p className={`${ui.fieldError} w-full`} role="alert">
          {error}
        </p>
      )}
    </form>
  )
}
